// ov: Openverse 사진 ID (상품마다 서로 다른 사진, 400개 상품 전체에서 중복 없음), lic: 라이선스
const OV_THUMB = id => 'https://api.openverse.org/v1/images/' + id + '/thumb/';
PRODUCTS.forEach(p => {
  const urls = p.ov.map(OV_THUMB);
  if (!p.imageRemote) p.imageRemote = urls.shift();
  p.photos = urls;
  p.credits = p.ov.map((id, i) => ({ id, license: p.lic[i], url: 'https://openverse.org/image/' + id }));
});

